import sys

def min_bridge_unavailability(N, arrival_times):
    bridge_up_until = 0
    total_unavailability = 0

    for T in arrival_times:
        if T > bridge_up_until:
            total_unavailability += T - bridge_up_until
            bridge_up_until = T + 20
        else:
            bridge_up_until += 20

        if bridge_up_until - T > 1800:
            return float('inf')

    return total_unavailability

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    arrival_times = [int(data[i]) for i in range(1, N+1)]

    result = min_bridge_unavailability(N, arrival_times)
    print(result)
